#include <stm32f103x6.h>

void delay(int x){
	for(volatile int i = 0;i<x*500;i++);
	return;
}

int main(void)
{
	RCC->APB2ENR |= (1 << 2); //Enable clock for port A GPIOs
	GPIOA->CRL &= ~(0xF << 20); // reset the CRL of GPIOA
	GPIOA->CRL |= (0b0010 << 20); // configuring the CRL as a general purpose output pin with  2 MHZ max speed

	while(1){
		GPIOA->ODR &= ~(1<<5); // set the output data register initially to zero (A*1 = A)
		delay(500); // delay for some time by making cpu waste time by counting
		GPIOA->ODR |= (1<<5); // set the output data register of pin 5 to 1
		delay(500); // delay again
		// loop infinitely
	};
}
